#include <stdint.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
/* Runs reverse communication until ido not in {1,2,5} or until aup2_iter changes.
   returns ido; *iter_changed flag returned via return code 1000+ido */
int run(void* fn, char* st, double* resid, double* v, int n, int* ipntr,
        double* workd, double* workl, const int32_t* indptr, const int32_t* indices,
        const double* data, int stop_on_iter)
{
    naupd_t f = (naupd_t)fn;
    int* ido = (int*)(st + 0x34);
    int* it = (int*)(st + 0x98);
    int last = *it;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        int d = *ido;
        if (d == 1 || d == 5) {
            const double* x = workd + ipntr[0];
            double* y = workd + ipntr[1];
            for (int i = 0; i < n; i++) {
                double acc = 0.0;
                for (int q = indptr[i]; q < indptr[i + 1]; q++) acc += data[q] * x[indices[q]];
                y[i] = acc;
            }
        } else if (d == 2) {
            const double* x = workd + ipntr[0];
            double* y = workd + ipntr[1];
            for (int i = 0; i < n; i++) y[i] = x[i];
        } else {
            return d;
        }
        if (stop_on_iter && *it != last) return 1000 + d;
    }
}
